/// `scale.ts` `radius`의 반경 단계입니다. 값은 논리 픽셀입니다.
///
/// React의 유틸리티는 이 이름으로 대응합니다: `rounded-xs`, `rounded-sm`, `rounded-md`,
/// `rounded-lg`, `rounded-xl`, `rounded-2xl`(-> [xl2]), `rounded-full`. 컴포넌트는
/// `HoronTheme.of(context).radius`에서 같은 이름으로 읽습니다.
abstract final class HoronRadius {
  static const double none = 0.0;
  static const double xs = 6.0;
  static const double sm = 8.0;
  static const double md = 12.0;
  static const double lg = 14.0;
  static const double xl = 20.0;
  static const double xl2 = 16.0;
  static const double full = 9999.0;
}

/// `scale.ts` `spacing`의 간격 단계입니다. 값은 논리 픽셀입니다.
///
/// Tailwind 간격 단위 1은 4px입니다. 그래서 `gap-1.5` = 6 = [s1_5], `px-4` = 16 = [s4]입니다.
/// 토큰에 없는 단위는 `HoronTheme.of(context).space.step(5.5)`로 계산합니다(22px).
abstract final class HoronSpace {
  static const double s0_5 = 2.0;
  static const double s1 = 4.0;
  static const double s1_5 = 6.0;
  static const double s2 = 8.0;
  static const double s2_5 = 10.0;
  static const double s3 = 12.0;
  static const double s3_5 = 14.0;
  static const double s4 = 16.0;
  static const double s5 = 20.0;
  static const double s6 = 24.0;
  static const double s8 = 32.0;
}

/// `scale.ts` `shadow`의 CSS 그림자를 Flutter [BoxShadow]로 옮긴 값입니다.
/// `popover`는 단단한 계정·워크스페이스 메뉴, `palette`는 커맨드 팔레트의 그림자입니다.
abstract final class HoronShadow {
  static const List<BoxShadow> popover = <BoxShadow>[
    BoxShadow(color: Color(0x1A0A0D0F), offset: Offset(0.0, 8.0), blurRadius: 24.0),
  ];
  static const List<BoxShadow> palette = <BoxShadow>[
    BoxShadow(color: Color(0x1F0A0D0F), offset: Offset(0.0, 16.0), blurRadius: 40.0),
  ];
}

/// 레이아웃 브레이크포인트입니다. 값은 논리 픽셀입니다.
///
/// `scale.ts`에는 브레이크포인트가 없습니다. React 세트가 컴파일되는 Tailwind v4 기본
/// 값을 그대로 옮겼고, 컴포넌트가 쓰는 `sm:`·`md:`·`lg:`·`xl:` 유틸리티가 이 값으로
/// 풀립니다. 호스트가 다른 브레이크포인트를 쓰면 이 값이 아니라 자기 값을 씁니다.
abstract final class HoronBreakpoint {
  static const double sm = 640.0;
  static const double md = 768.0;
  static const double lg = 1024.0;
  static const double xl = 1280.0;
  static const double xl2 = 1536.0;
}

/// `typography.ts` `fontWeight`의 네 제품 굵기입니다. Thin과 Light는 제품에 없습니다.
abstract final class HoronFontWeight {
  static const FontWeight regular = FontWeight.w400;
  static const FontWeight medium = FontWeight.w500;
  static const FontWeight semibold = FontWeight.w600;
  static const FontWeight bold = FontWeight.w700;
